export { FormBuilder } from '@/components/formedible/builder/form-builder';
export { FieldConfigurator } from '@/components/formedible/builder/field-configurator';
export { FormPreview } from '@/components/formedible/builder/form-preview';
export { CodeGenerator } from '@/components/formedible/builder/code-generator';
export { FieldStore, globalFieldStore } from '@/components/formedible/builder/field-store';
export {
  builderTab,
  codeTab,
  createTabsWithDisabled,
  createTabsWithOrder,
  defaultTabs,
  getBuilderAndCodeTabs,
  getBuilderAndPreviewTabs,
  getBuilderOnlyTabs,
  previewTab,
} from '@/components/formedible/builder/default-tabs';
export { defaultFormMetadata, builderFieldTypes } from '@/lib/formedible/builder-types';
export { generateCodeFromParsedConfig, generateFormCode } from '@/lib/formedible/code-generation';
export type {
  BuilderFieldTypeDefinition,
  FormBuilderProps,
  FormField,
  FormMetadata,
  FormPage,
  FormSettings,
  FormTab,
  TabConfig,
  TabContentProps,
} from '@/lib/formedible/builder-types';
export type { CodeGenerationOptions, GeneratedCodeResult } from '@/lib/formedible/code-generation';

'use client';

import { useEffect, useMemo, useState, useSyncExternalStore } from 'react';

import { Button } from '@/components/ui/button';
import { globalFieldStore } from '@/components/formedible/builder/field-store';
import { defaultTabs } from '@/components/formedible/builder/default-tabs';
import { cn } from '@/lib/utils';
import { defaultFormMetadata } from '@/lib/formedible/builder-types';
import type { FormBuilderProps, FormMetadata, TabConfig } from '@/lib/formedible/builder-types';
import type { FormedibleFieldType } from '@/lib/formedible/types';

const emptyInitialFields: NonNullable<FormBuilderProps['initialFields']> = [];

function orderTabs(tabs: readonly TabConfig[]): readonly TabConfig[] {
  return [...tabs]
    .filter((tab) => tab.enabled !== false)
    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0));
}

export function FormBuilder({
  tabs = defaultTabs,
  defaultTab = 'builder',
  initialMetadata,
  initialFields,
  onChange,
  onTabChange,
  onSubmit,
  className,
}: FormBuilderProps) {
  const sortedTabs = useMemo(() => orderTabs(tabs), [tabs]);
  const initialTab = sortedTabs.some((tab) => tab.id === defaultTab) ? defaultTab : sortedTabs[0]?.id ?? 'builder';
  const [activeTab, setActiveTab] = useState(initialTab);
  const [selectedFieldId, setSelectedFieldId] = useState<string | null>(null);
  const [metadata, setMetadata] = useState<FormMetadata>({
    ...defaultFormMetadata,
    ...initialMetadata,
    settings: {
      ...defaultFormMetadata.settings,
      ...initialMetadata?.settings,
    },
  });
  const importedInitialFields = initialFields ?? emptyInitialFields;
  const fields = useSyncExternalStore(
    (listener) => globalFieldStore.subscribe(listener),
    () => globalFieldStore.getAllFields(),
    () => importedInitialFields,
  );

  useEffect(() => {
    globalFieldStore.importFields(importedInitialFields);
  }, [importedInitialFields]);

  useEffect(() => {
    onChange?.(metadata, fields);
  }, [fields, metadata, onChange]);

  function updateMetadata(metadataUpdate: Partial<FormMetadata>): void {
    setMetadata((currentMetadata) => ({
      ...currentMetadata,
      ...metadataUpdate,
      settings: {
        ...currentMetadata.settings,
        ...metadataUpdate.settings,
      },
    }));
  }

  function addField(type: FormedibleFieldType): void {
    const fieldId = globalFieldStore.addField(type, metadata.pages[0]?.page ?? 1);
    setSelectedFieldId(fieldId);
  }

  function deleteField(fieldId: string): void {
    globalFieldStore.deleteField(fieldId);
    setSelectedFieldId((currentFieldId) => (currentFieldId === fieldId ? null : currentFieldId));
  }

  function duplicateField(fieldId: string): void {
    const duplicatedFieldId = globalFieldStore.duplicateField(fieldId);

    if (duplicatedFieldId !== null) {
      setSelectedFieldId(duplicatedFieldId);
    }
  }

  const activeTabConfig = sortedTabs.find((tab) => tab.id === activeTab) ?? sortedTabs[0];
  const ActiveTabComponent = activeTabConfig?.component;

  return (
    <div className={cn('flex min-h-[720px] flex-col rounded-xl border bg-background text-foreground', className)} data-builder-part="form-builder">
      <div className="flex flex-wrap items-center gap-3 border-b p-4">
        <div className="mr-auto">
          <h1 className="text-xl font-semibold">{metadata.title}</h1>
          <p className="text-sm text-muted-foreground">{metadata.description}</p>
        </div>
        <Button type="button" variant="outline" onClick={() => onSubmit?.(metadata, fields)}>
          Save Form
        </Button>
      </div>

      <div className="flex flex-wrap gap-2 border-b p-3">
        {sortedTabs.map((tab) => {
          const Icon = tab.icon;

          return (
            <Button
              key={tab.id}
              type="button"
              variant={tab.id === activeTab ? 'default' : 'ghost'}
              onClick={() => {
                setActiveTab(tab.id);
                onTabChange?.(tab.id);
              }}
            >
              {Icon !== undefined ? <Icon className="mr-2 size-4" /> : null}
              {tab.label}
            </Button>
          );
        })}
      </div>

      <div className="flex-1 p-4">
        {ActiveTabComponent !== undefined ? (
          <ActiveTabComponent
            metadata={metadata}
            fields={fields}
            selectedFieldId={selectedFieldId}
            onMetadataChange={updateMetadata}
            onAddField={addField}
            onSelectField={setSelectedFieldId}
            onDeleteField={deleteField}
            onDuplicateField={duplicateField}
          />
        ) : null}
      </div>
    </div>
  );
}

'use client';

import { useSyncExternalStore } from 'react';

import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Field, FieldDescription, FieldLabel } from '@/components/ui/field';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';
import { globalFieldStore } from '@/components/formedible/builder/field-store';
import type { FormField } from '@/lib/formedible/builder-types';

export interface FieldConfiguratorProps {
  readonly fieldId: string;
  readonly initialField: FormField;
  readonly availablePages?: readonly number[];
  readonly onFieldChange?: (field: FormField) => void;
  readonly className?: string;
}

export function FieldConfigurator({
  fieldId,
  initialField,
  availablePages = [1],
  onFieldChange,
  className,
}: FieldConfiguratorProps) {
  const field = useSyncExternalStore(
    (listener) => globalFieldStore.subscribeToFieldUpdates(fieldId, listener),
    () => globalFieldStore.getField(fieldId) ?? initialField,
    () => initialField,
  );

  function updateField(fieldUpdate: Partial<FormField>): void {
    const updatedField = globalFieldStore.updateField(fieldId, fieldUpdate) ?? globalFieldStore.replaceField(fieldId, {
      ...field,
      ...fieldUpdate,
    });
    onFieldChange?.(updatedField);
  }

  const optionsText = Array.isArray(field.options)
    ? field.options.map((option) => (typeof option === 'string' ? option : option.value)).join('\n')
    : '';

  return (
    <div className={cn('space-y-4 rounded-lg border bg-card p-4 text-card-foreground', className)} data-builder-part="field-configurator">
      <div>
        <h2 className="text-lg font-semibold">Configure Field</h2>
        <p className="text-sm text-muted-foreground">Update the selected field metadata and behavior.</p>
      </div>

      <Field>
        <FieldLabel htmlFor={`${fieldId}-label`}>Label</FieldLabel>
        <Input
          id={`${fieldId}-label`}
          value={String(field.label)}
          onChange={(event) => updateField({ label: event.currentTarget.value })}
        />
      </Field>

      <Field>
        <FieldLabel htmlFor={`${fieldId}-name`}>Name</FieldLabel>
        <Input
          id={`${fieldId}-name`}
          value={field.name}
          onChange={(event) => updateField({ name: event.currentTarget.value })}
        />
      </Field>

      <Field>
        <FieldLabel htmlFor={`${fieldId}-placeholder`}>Placeholder</FieldLabel>
        <Input
          id={`${fieldId}-placeholder`}
          value={field.placeholder ?? ''}
          onChange={(event) => updateField({ placeholder: event.currentTarget.value })}
        />
      </Field>

      <Field>
        <FieldLabel htmlFor={`${fieldId}-description`}>Description</FieldLabel>
        <Textarea
          id={`${fieldId}-description`}
          value={String(field.description ?? '')}
          onChange={(event) => updateField({ description: event.currentTarget.value })}
        />
      </Field>

      <Field className="flex flex-row items-center gap-3">
        <Checkbox
          id={`${fieldId}-required`}
          checked={field.required === true}
          onCheckedChange={(checked) => updateField({ required: checked === true })}
        />
        <FieldLabel htmlFor={`${fieldId}-required`}>Required</FieldLabel>
      </Field>

      {availablePages.length > 1 ? (
        <Field>
          <FieldLabel>Page</FieldLabel>
          <div className="flex flex-wrap gap-2">
            {availablePages.map((page) => (
              <Button
                key={page}
                type="button"
                variant={(field.page ?? 1) === page ? 'default' : 'outline'}
                size="sm"
                onClick={() => updateField({ page })}
              >
                Page {page}
              </Button>
            ))}
          </div>
        </Field>
      ) : null}

      {field.type === 'select' || field.type === 'radio' || field.type === 'multiSelect' ? (
        <Field>
          <FieldLabel htmlFor={`${fieldId}-options`}>Options</FieldLabel>
          <Textarea
            id={`${fieldId}-options`}
            value={optionsText}
            onChange={(event) => updateField({ options: event.currentTarget.value.split('\n').filter((option) => option.length > 0) })}
          />
          <FieldDescription>One option per line.</FieldDescription>
        </Field>
      ) : null}

      {field.type === 'number' || field.type === 'slider' || field.type === 'rating' ? (
        <div className="grid gap-4 sm:grid-cols-3">
          <Field>
            <FieldLabel htmlFor={`${fieldId}-min`}>Min</FieldLabel>
            <Input
              id={`${fieldId}-min`}
              type="number"
              value={field.min ?? ''}
              onChange={(event) => updateField({ min: event.currentTarget.valueAsNumber })}
            />
          </Field>
          <Field>
            <FieldLabel htmlFor={`${fieldId}-max`}>Max</FieldLabel>
            <Input
              id={`${fieldId}-max`}
              type="number"
              value={field.max ?? ''}
              onChange={(event) => updateField({ max: event.currentTarget.valueAsNumber })}
            />
          </Field>
          <Field>
            <FieldLabel htmlFor={`${fieldId}-step`}>Step</FieldLabel>
            <Input
              id={`${fieldId}-step`}
              type="number"
              value={field.step ?? ''}
              onChange={(event) => updateField({ step: event.currentTarget.valueAsNumber })}
            />
          </Field>
        </div>
      ) : null}
    </div>
  );
}

'use client';

import { useMemo } from 'react';

import { useFormedible } from '@/hooks/use-formedible';
import { cn } from '@/lib/utils';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/lib/formedible/types';

export interface FormPreviewProps {
  readonly config: UseFormedibleOptions<FormedibleFormValues>;
  readonly onFormSubmit?: (values: FormedibleFormValues) => void;
  readonly className?: string;
}

export function FormPreview({ config, onFormSubmit, className }: FormPreviewProps) {
  const previewConfig = useMemo<UseFormedibleOptions<FormedibleFormValues>>(() => ({
    ...config,
    formOptions: {
      ...config.formOptions,
      defaultValues: config.formOptions.defaultValues,
      onSubmit: async ({ value }) => {
        onFormSubmit?.(value);
      },
    },
  }), [config, onFormSubmit]);
  const { Form } = useFormedible(previewConfig);

  if (config.fields.length === 0) {
    return (
      <div className={cn('rounded-lg border border-dashed p-8 text-center text-sm text-muted-foreground', className)} data-builder-part="form-preview-empty">
        Add fields to preview the form.
      </div>
    );
  }

  return (
    <div className={cn('rounded-lg border bg-background p-4', className)} data-builder-part="form-preview">
      <Form />
    </div>
  );
}

